import sys

def solve(s=None):
    """Convert a Roman numeral to an integer.
    If s is provided, return the integer value. Otherwise, read a line from stdin.
    """
    if s is None:
        data = sys.stdin.read().strip()
        s = data.splitlines()[0] if data else ''
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman[s[i]] < roman[s[i+1]]:
            total += roman[s[i+1]] - roman[s[i]]
            i += 2
        else:
            total += roman[s[i]]
            i += 1
    return total

if __name__ == "__main__":
    result = solve()
    if result is not None:
        print(result)

