def solve(tokens):
    """Evaluate an RPN expression with integer arithmetic.
    Division truncates toward zero without using floating point.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # handle division by zero gracefully (though shouldn't occur)
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # compute truncating division using integer arithmetic
                sign = -1 if (a * b) < 0 else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

