def solve(s):
    # Return list of [char, count] for consecutive runs in s.
    if not s:
        return []
    res = []
    prev = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = ch
            cnt = 1
    res.append([prev, cnt])
    return res

