    """Levenshtein distance with O(min(m,n)) space.
    """
    if len(a) < len(b):
        a, b = b, a  # ensure a is the longer string
    m, n = len(a), len(b)
    # previous row
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                 cur[j - 1],   # insertion
                                 prev[j - 1])   # substitution
        prev = cur
    return prev[n]

