import sys, ast

def solve(tokens=None):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings. If None, read a Python list literal from stdin.
    Returns integer with division truncating toward zero.
    """
    if tokens is None:
        data = sys.stdin.read().strip()
        if not data:
            return None
        tokens = ast.literal_eval(data)
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else None

if __name__ == "__main__":
    result = solve()
    if result is not None:
        print(result)

